begin;
do $$
declare u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();lead uuid;other_lead uuid;app uuid;foreign_app uuid;artifact uuid:=gen_random_uuid();goal uuid:=gen_random_uuid();k text:=repeat('e',64);p jsonb;r jsonb;foreign_key text:=repeat('f',64);
begin
 insert into auth.users(id) values(u),(v);
 insert into public.search_listings(user_id,identity,canonical_url,company,title,match_key) values(u,'evolution','https://example.com/evolution','Example','Engineer','example-engineer') returning id into lead;
 if (select job_id from public.search_listings where id=lead) is not null then raise exception 'Unpublished lead acquired a job';end if;
 insert into public.jobs(id,canonical_url,employer) values('evolution-job','https://example.com/evolution','{}');
 if (select job_id from public.search_listings where id=lead) is distinct from 'evolution-job' then raise exception 'Publication did not link existing lead';end if;
 insert into public.search_listings(user_id,identity,canonical_url,company,title,match_key) values(v,'evolution','https://example.com/evolution','Example','Engineer','example-engineer') returning id into other_lead;
 if (select job_id from public.search_listings where id=other_lead) is distinct from 'evolution-job' then raise exception 'New lead did not link existing publication';end if;
 update public.search_listings set canonical_url='https://example.com/another' where id=other_lead;
 if (select job_id from public.search_listings where id=other_lead) is not null then raise exception 'Changed URL kept stale job';end if;
 update public.jobs set canonical_url='https://example.com/another' where id='evolution-job';
 if (select job_id from public.search_listings where id=lead) is not null or (select job_id from public.search_listings where id=other_lead) is distinct from 'evolution-job' then raise exception 'Changed publication URL left stale links';end if;
 delete from public.jobs where id='evolution-job';
 if (select job_id from public.search_listings where id=other_lead) is not null then raise exception 'Deleted publication left dangling link';end if;
 insert into public.jobs(id,canonical_url,employer) values('evolution-job','https://example.com/evolution','{}');
 insert into public.applications(user_id,job_id) values(u,'evolution-job') returning id into app;
 insert into public.applications(user_id,job_id) values(v,'evolution-job') returning id into foreign_app;
 insert into public.company_workspaces(user_id,id,name) values(u,'my-target','Example'),(v,'other-target','Other');
 insert into public.outreach_contacts(user_id,id,record) values(u,'my-contact','{"contact":"Fictional person"}'),(v,'other-contact','{"contact":"Other person"}');
 insert into public.learning_goals(id,user_id,goal) values(goal,u,'{"title":"Systems","objective":"Practice","active":true,"tasks":[]}');
 insert into private.agent_connections(user_id,name,token_hash,scopes,expires_at) values(u,'Evolution',k,array['workspace:read','drafts:write'],now()+interval '1 hour'),(v,'Other',foreign_key,array['workspace:read','drafts:write'],now()+interval '1 hour');
 perform set_config('test.uid',u::text,true);
 p:=jsonb_build_object('id',artifact,'expectedVersion',0,'title','Research with caveats','purpose','Prepare a decision','kind','company_research','format','markdown','body',E'# Analysis\n\nHypothesis, not verified candidate evidence.','sources','[]'::jsonb,'links',jsonb_build_array(jsonb_build_object('applicationId',app),jsonb_build_object('goalId',goal),jsonb_build_object('companyWorkspaceId','my-target'),jsonb_build_object('contactId','my-contact'),jsonb_build_object('jobId','evolution-job')));
 execute 'set local role authenticated';
 r:=public.artifact_action('artifacts.save',p);
 execute 'reset role';
 if public.agent_dispatch(k,'artifacts.save',p) is distinct from r then raise exception 'Website/MCP retry mismatch';end if;
 if public.agent_dispatch(k,'artifacts.list','{"companyWorkspaceId":"my-target"}')->'items'->0->>'id' is distinct from artifact::text then raise exception 'Company link filter lost';end if;
 if public.artifact_action('artifacts.list','{"contactId":"my-contact"}')->'items'->0->>'id' is distinct from artifact::text then raise exception 'Contact link filter lost';end if;
 if jsonb_array_length(public.agent_dispatch(foreign_key,'artifacts.list','{"jobId":"evolution-job"}')->'items')<>0 then raise exception 'Shared job exposed private analysis';end if;
 begin perform public.artifact_action('artifacts.save',p||jsonb_build_object('id',gen_random_uuid(),'links',jsonb_build_array(jsonb_build_object('applicationId',foreign_app))));raise exception 'Foreign application accepted';exception when no_data_found then null;end;
 begin perform public.agent_dispatch(k,'artifacts.save',p||jsonb_build_object('id',gen_random_uuid(),'links','[{"companyWorkspaceId":"other-target"}]'::jsonb));raise exception 'Foreign company accepted';exception when no_data_found then null;end;
 begin perform public.artifact_action('artifacts.save',p||jsonb_build_object('id',gen_random_uuid(),'links','[{"contactId":"other-contact"}]'::jsonb));raise exception 'Foreign contact accepted';exception when no_data_found then null;end;
 begin perform public.agent_dispatch(k,'artifacts.save',p||jsonb_build_object('id',gen_random_uuid(),'links','[{"jobId":"missing"}]'::jsonb));raise exception 'Missing job accepted';exception when no_data_found then null;end;
 begin perform public.artifact_action('artifacts.save',p||jsonb_build_object('id',gen_random_uuid(),'links','[{"jobId":"evolution-job","taskId":"fake"}]'::jsonb));raise exception 'Fake task accepted';exception when invalid_parameter_value then null;end;
 begin perform public.agent_dispatch(k,'artifacts.save',p||jsonb_build_object('id',gen_random_uuid(),'links','[{"contactId":"my-contact"},{"contactId":"my-contact"}]'::jsonb));raise exception 'Duplicate subjects accepted';exception when invalid_parameter_value then null;end;
 perform public.agent_dispatch(k,'artifacts.save',p||'{"expectedVersion":1,"body":"Revised analysis"}');
 begin perform public.artifact_action('artifacts.save',p||'{"body":"Stale analysis"}');raise exception 'Stale revision accepted';exception when serialization_failure then null;end;
 if public.artifact_action('artifacts.read',jsonb_build_object('id',artifact,'version',1))->'content' is distinct from p-array['id','expectedVersion'] then raise exception 'Historical document or links changed';end if;
 execute 'set local role authenticated';
 if (select count(*) from public.search_listings where id=other_lead)<>0 then raise exception 'Foreign lead exposed';end if;
 execute 'reset role';
end $$;
rollback;
